  ('f(x) = e^e fonksiyonunun türevi kaçtır? (e Euler sayısıdır.)', '0', ['e^e', 'e^(e − 1)', 'e·e^e'], 'e^e bir sabittir; sabitin türevi sıfırdır.'),
  ('f(x) = ln|x| fonksiyonunun x ≠ 0 için türevi hangisidir?', '1/x', ['1/|x|', '−1/x', '|x|'], 'x < 0 için ln(−x)\'in türevi (−1)/(−x) = 1/x\'tir; böylece her x ≠ 0 için 1/x elde edilir.'),
  ('x² + y² = 25 çemberi üzerindeki (3, 4) noktasında dy/dx değeri kaçtır?', '−3/4', ['3/4', '−4/3', '4/3'], '2x + 2y y\' = 0 olduğundan y\' = −x/y = −3/4.'),
  ('xy = 1 eğrisi üzerindeki (1, 1) noktasında kapalı türev alınırsa dy/dx hangi değeri alır?', '−1', ['1', '0', '−2'], 'y + x y\' = 0 ve y\' = −y/x = −1.'),
  ('x²y = 4 bağıntısıyla verilen eğrinin (1, 4) noktasındaki eğimi nedir?', '−8', ['8', '−4', '−2'], '2xy + x² y\' = 0 → 8 + y\' = 0 ve y\' = −8.'),
  ('x = t², y = t³ parametrik denklemleriyle verilen eğrinin t = 2 için dy/dx değeri kaçtır?', '3', ['6', '3/2', '12'], 'dy/dx = (3t²)/(2t) = 3t/2; t = 2 için 3.'),
  ('x = cos t, y = sin t ile verilen çember üzerinde t = π/4 noktasındaki teğetin eğimi nedir?', '−1', ['1', '−√2', '0'], 'dy/dx = cos t/(−sin t) = −cot t; t = π/4 için −1.'),
  ('x = 2t + 1, y = t² − t denklemleri için t = 3 noktasındaki dy/dx kaçtır?', '5/2', ['5', '2/5', '−5/2'], 'dy/dx = (2t − 1)/2; t = 3 için 5/2.'),
  ('f(x) = ln x fonksiyonunun üçüncü türevi hangisidir?', '2/x³', ['−2/x³', '1/x³', '−1/x²'], 'f\' = 1/x, f\'\' = −1/x², f\'\'\' = 2/x³.'),
  ('f(x) = x⁵ fonksiyonunun altıncı mertebeden türevi nedir?', '0', ['120', '1', '5!·x'], 'Beşinci türev sabit 120\'dir; bir sonraki türev 0 olur.'),
  ('f(x) = x·eˣ için f\'\'(0) kaçtır?', '2', ['1', '0', '−2'], 'f\' = (x + 1)eˣ, f\'\' = (x + 2)eˣ; x = 0 için 2.'),
  ('f(x) = e^(−x) fonksiyonunun yedinci türevinin x = 0\'daki değeri kaçtır?', '−1', ['1', '7', '−7'], 'f⁽ⁿ⁾(x) = (−1)ⁿ e^(−x) olduğundan n = 7 için −1.'),
  ('f(x) = x³ − 3x² fonksiyonu hangi aralıkta azalandır?', '(0, 2)', ['(−∞, 0)', '(2, ∞)', '(−2, 0)'], 'f\'(x) = 3x(x − 2) olur ve yalnızca 0 < x < 2 için negatiftir.'),
  ('f(x) = x·e^(−x) fonksiyonunun yerel maksimum değeri nedir?', '1/e', ['1', 'e', '1/e²'], 'f\'(x) = (1 − x)e^(−x), x = 1\'de işaret + dan − ye geçer. f(1) = 1/e.'),
  ('Pozitif x değerleri için bir sayı ile çarpmaya göre tersinin toplamını veren x + 1/x ifadesi en az hangi değeri alabilir?', '2', ['1', '1/2', '4'], 'f\'(x) = 1 − 1/x² = 0 için x = 1. f(1) = 2; bu aritmetik–geometrik ortalama eşitsizliğiyle de uyumludur.'),
  ('f(x) = x³ − 3x + 2 fonksiyonunun yerel maksimum değeri ile yerel minimum değerinin farkı kaçtır?', '4', ['2', '0', '4,5'], 'f\'(x) = 3x² − 3 = 0 için x = ±1. f(−1) = 4, f(1) = 0; fark 4.'),
  ('f\'(2) = 0 olan bir fonksiyonun türevi x = 2\'de negatiften pozitife geçiyorsa bu nokta için ne söylenir?', 'Yerel minimum noktasıdır', ['Yerel maksimum noktasıdır', 'Büküm noktasıdır', 'Süreksizlik noktasıdır'], 'Birinci türev testine göre türev işaretinin − dan + ya geçtiği yerde fonksiyon azalmayı bırakıp artmaya başlar; yerel minimum oluşur.'),
  ('f(x) = x³ − 6x² + 9x fonksiyonunun büküm noktası aşağıdakilerden hangisidir?', '(2, 2)', ['(1, 4)', '(2, 0)', '(−2, 2)'], 'f\'\'(x) = 6x − 12 = 0 için x = 2 ve f(2) = 8 − 24 + 18 = 2.'),
  ('f(x) = x·eˣ fonksiyonunun grafiği hangi noktada konkavlık değiştirir (büküm apsisi)?', 'x = −2', ['x = −1', 'x = 0', 'x = 2'], 'f\'\' = (x + 2)eˣ olur ve x = −2\'de işaret değiştirir.'),
  ('f(x) = x³ − 3x fonksiyonunun [0, 3] kapalı aralığındaki en büyük değeri ile en küçük değeri arasındaki fark kaçtır?', '20', ['18', '16', '200'], 'f\'(x) = 0 için x = 1; f(0) = 0, f(1) = −2, f(3) = 18. Fark 18 − (−2) = 20.'),
  ('[0, 2π] aralığında sin x + cos x ifadesinin alabileceği en büyük değer nedir?', '√2', ['2', '1', 'π/2'], 'sin x + cos x = √2 sin(x + π/4) olarak yazılır; en büyük değeri √2\'dir.'),
  ('f(x) = x² − 4x + 4 fonksiyonunun [0, 5] aralığındaki mutlak maksimumu kaçtır?', '9', ['4', '0', '9,5'], 'f(x) = (x − 2)²\'dir; uç noktalarda f(0) = 4, f(5) = 9 ve tepe değeri 0\'dır. En büyüğü 9.'),
  ('f(x) = x/(x² + 4) fonksiyonunun x ≥ 0 için alabileceği en büyük değer nedir?', '1/4', ['1/2', '1/8', '1/20'], 'f\'(x) = (4 − x²)/(x² + 4)² → x = 2. f(2) = 2/8 = 1/4.'),
  ('Bir kenarı duvara dayalı ve diğer üç kenarı 100 metrelik telle çevrilen dikdörtgen bahçenin en büyük alanı kaç metrekaredir?', '1250', ['2500', '625', '12500'], 'Duvara dik kenarlar x ise karşı kenar 100 − 2x\'tir. A = x(100 − 2x) en büyük değerini x = 25\'te alır: 25·50 = 1250.'),
  ('Bir firmanın kârı P(x) = −x² + 40x − 100 liradır (x üretim adedi). En büyük kâr kaç liradır?', '300', ['400', '200', '3000'], 'P\'(x) = −2x + 40 = 0 → x = 20 ve P(20) = −400 + 800 − 100 = 300.'),
  ('Kenarı 3 cm/s hızla uzayan bir karenin kenarı 10 cm iken alanı hangi hızla (cm²/s) artmaktadır?', '60', ['30', '100', '300'], 'A = a² → dA/dt = 2a·da/dt = 2·10·3 = 60.'),
  ('Bir damla suyun dairesel lekesinin yarıçapı 3 cm/s hızla büyüyor. Yarıçap 4 cm iken leke alanı saniyede kaç cm² artar?', '24π', ['12π', '48π', '324π'], 'A = πr² → dA/dt = 2πr·dr/dt = 2π·4·3 = 24π.'),
  ('s(t) = t² − 4t konum fonksiyonuna sahip cisim hangi anda yön değiştirir?', 't = 2', ['t = 4', 't = 1', 't = 0'], 'v(t) = 2t − 4 olur, işaret t = 2\'de negatiften pozitife geçer.'),
  ('s(t) = t³ − 6t² + 9t konum fonksiyonu için t = 3 anındaki ivme kaç birimdir?', '6', ['0', '9', '18'], 'a(t) = s\'\'(t) = 6t − 12 olduğundan a(3) = 6.'),
  ('Bir araç 2 saatte 240 km yol almıştır. Ortalama değer teoremine göre bu yolculuk sırasında ne kesin olarak söylenebilir?', 'Bir anda anlık hızı tam 120 km/sa olmuştur', ['Araç sürekli 120 km/sa hızla gitmiştir', 'En yüksek hızı 120 km/sa olmuştur', 'Hiçbir zaman 120 km/sa hızı aşmamıştır'], 'Ortalama hız 120 km/sa\'tir. Teorem, türevin (anlık hızın) bu değere eşit olduğu bir an bulunduğunu garanti eder.'),
  ('f(x) = x² − 4x + 3 fonksiyonu için [1, 3] aralığında Rolle teoremini sağlayan c noktası kaçtır?', '2', ['1', '3/2', '0'], 'f(1) = f(3) = 0 olduğundan Rolle uygulanır. f\'(c) = 2c − 4 = 0 → c = 2.'),
  ('Doğrusal yaklaşım (diferansiyel) kullanılarak √25,3 değeri yaklaşık kaç bulunur?', '5,03', ['5,3', '5,13', '5,003'], 'f(x) = √x, f\'(25) = 1/10 ve Δx = 0,3. √25,3 ≈ 5 + 0,3/10 = 5,03.'),
  ('Diferansiyel yaklaşımıyla ∛8,12 değeri yaklaşık kaçtır?', '2,01', ['2,12', '2,001', '2,06'], 'f(x) = x^(1/3), f\'(8) = 1/12 ve Δx = 0,12. ∛8,12 ≈ 2 + 0,12/12 = 2,01.'),
  ('Yaklaşık değer hesabıyla ln(1,05) hangi sayıya çok yakındır?', '0,05', ['0,5', '1,05', '0,005'], 'f(x) = ln x ve f\'(1) = 1 olduğundan ln(1,05) ≈ 0 + 1·0,05 = 0,05.'),
  ('Yarıçapı 10 cm olarak ölçülen bir kürenin yarıçapı 0,1 cm hatalı ölçülmüşse hacimdeki yaklaşık hata kaç cm³\'tür?', '40π', ['4π', '400π', '20π'], 'dV = 4πr² dr = 4π·100·0,1 = 40π.'),
  ('y = x³ fonksiyonunda x = 2\'den dx = 0,1 artışıyla Δy ile dy arasındaki fark (Δy − dy) kaçtır?', '0,061', ['0,1', '1,2', '−0,061'], 'Δy = 2,1³ − 8 = 1,261 ve dy = 12·0,1 = 1,2. Fark 0,061.'),
  ('Bir küpün kenar uzunluğu ölçülürken yaklaşık %2 hata yapılmıştır. Küpün hacmindeki bağıl hata yaklaşık kaç yüzdedir?', '%6', ['%2', '%4', '%8'], 'V = a³ → dV/V = 3·da/a = 3·%2 = %6.'),
  ('Doğrusal yaklaşımla (1,02)¹⁰ ifadesinin değeri yaklaşık kaçtır?', '1,2', ['1,02', '1,002', '2,0'], 'f(x) = x¹⁰ için f\'(1) = 10. (1,02)¹⁰ ≈ 1 + 10·0,02 = 1,2.'),
  ('Kuvvet fonksiyonu 1/x² için belirsiz integral ∫ x⁻² dx aşağıdakilerden hangisidir?', '−1/x + C', ['1/x + C', '−2/x³ + C', 'ln x² + C'], '∫ xⁿ dx = xⁿ⁺¹/(n + 1) + C formülüyle n = −2 için x⁻¹/(−1) = −1/x.'),
  ('Türevi 1/(1 + x²) ifadesine eşit olan ters trigonometrik fonksiyon aşağıdakilerden hangisidir? (C keyfi sabit)', 'arctan x + C', ['ln(1 + x²) + C', 'arcsin x + C', '−1/(1 + x²)² + C'], 'arctan x\'in türevi 1/(1 + x²) olduğundan ilkel arctan x + C\'dir.'),
  ('1/√(1 − x²) fonksiyonunun ilkeli aşağıdakilerden hangisidir?', 'arcsin x + C', ['arctan x + C', '√(1 − x²) + C', 'ln|1 − x²| + C'], 'arcsin x\'in türevi 1/√(1 − x²)\'dir. arccos x\'in türevi bunun negatifi olduğundan arccos x + C bu fonksiyonun ilkeli değildir.'),
  ('sec²x fonksiyonunun belirsiz integrali nedir?', 'tan x + C', ['cot x + C', 'sec x + C', '−tan x + C'], 'tan x\'in türevi sec²x\'tir.'),
  ('Üssünde değişken bulunan 3ˣ fonksiyonunun ilkeli, yani x\'e göre antitürevi, hangi ifadeyle verilir?', '3ˣ/ln 3 + C', ['3ˣ·ln 3 + C', '3ˣ⁺¹/(x + 1) + C', '3ˣ + C'], 'd/dx(3ˣ) = 3ˣ ln 3 olduğundan ilkel 3ˣ/ln 3 + C\'dir.'),
  ('İç fonksiyonu 3x olan kosinüs ifadesinin antitürevini bulmak için hangi sonuç kullanılır? Hesap: ∫ cos(3x) dx.', 'sin(3x)/3 + C', ['3 sin(3x) + C', '−sin(3x)/3 + C', 'sin(3x) + C'], 'İç fonksiyon 3x\'in türevi 3 olduğundan 1/3 katsayısı eklenir.'),
  ('Küp kök fonksiyonu ∛x için ∫ ∛x dx integrali hangisidir?', '(3/4)x^(4/3) + C', ['(4/3)x^(4/3) + C', '(3/2)x^(2/3) + C', '(1/3)x^(−2/3) + C'], 'x^(1/3)\'ün ilkeli x^(4/3)/(4/3) = (3/4)x^(4/3)\'tür.'),
  ('(x³ − 1)/x² kesrinin (x ≠ 0) belirsiz integrali hangisidir?', 'x²/2 + 1/x + C', ['x²/2 − 1/x + C', 'x⁴/4 + 1/x + C', 'x²/2 + ln|x| + C'], 'İfade x − x⁻² olarak yazılır. İntegrali x²/2 − (−x⁻¹) = x²/2 + 1/x\'tir.'),
  ('f\'(x) = 6x² − 2 ve f(1) = 5 olduğuna göre f(2) kaçtır?', '17', ['14', '12', '−17'], 'f(x) = 2x³ − 2x + C ve f(1) = 5 ise C = 5. f(2) = 16 − 4 + 5 = 17.'),
  ('Her noktadaki teğetinin eğimi 2x olan ve (1, 3) noktasından geçen eğri üzerinde, apsisi 2 olan noktanın ordinatı kaçtır?', '6', ['4', '5', '6,5'], 'y = x² + C ve 1 + C = 3\'ten C = 2 bulunur. x = 2 için y = 6.'),
  ('Sinüsün karesi için yarım açı özdeşliği kullanılarak ∫ sin²x dx hesaplanırsa hangi ilkel elde edilir?', 'x/2 − sin(2x)/4 + C', ['x/2 + sin(2x)/4 + C', 'sin³x/3 + C', '−cos²x/2 + C'], 'sin²x = (1 − cos 2x)/2 özdeşliği terim terim integre edilir.'),
  ('Paydası 2x + 1 olan basit bir kesrin, yani ∫ 1/(2x + 1) dx ifadesinin ilkeli (x > −1/2) nedir?', '(1/2) ln(2x + 1) + C', ['ln(2x + 1) + C', '2 ln(2x + 1) + C', '−1/(2x + 1)² + C'], 'İç fonksiyonun türevi 2 olduğundan integralin önüne 1/2 gelir.'),
  ('∫ cos x · e^(sin x) dx integralinin sonucu nedir?', 'e^(sin x) + C', ['e^(cos x) + C', 'cos x·e^(sin x) + C', 'sin x·e^(sin x) + C'], 'u = sin x seçilirse du = cos x dx olur ve ∫ eᵘ du = eᵘ.'),
  ('x > 1 için ∫ 1/(x ln x) dx integralinin sonucu hangisidir?', 'ln(ln x) + C', ['(ln x)²/2 + C', 'ln x + C', '1/(ln x)² + C'], 'u = ln x dersek ∫ du/u = ln|u| = ln(ln x) olur.'),
  ('∫ (2x + 1)/(x² + x + 5) dx integrali hangisine eşittir?', 'ln(x² + x + 5) + C', ['2 ln(x² + x + 5) + C', '(2x + 1)² + C', 'arctan(x² + x + 5) + C'], 'Payın değeri paydanın türevidir; ∫ u\'/u = ln|u|.'),
  ('Üstel kuvveti x² olan ve çarpanı x bulunan x·e^(x²) fonksiyonunun 0 ile 1 arasındaki alan değeri nedir?', '(e − 1)/2', ['e − 1', 'e/2', '(e² − 1)/2'], 'u = x² ile ∫₀¹ eᵘ du/2 = (e − 1)/2.'),
  ('∫₀^(π/2) sin³x cos x dx değeri kaçtır?', '1/4', ['1/3', '1/2', '−1/4'], 'u = sin x ile ∫₀¹ u³ du = 1/4.'),
  ('Pay kısmında ln x\'in karesi, paydada x bulunan fonksiyonun 1\'den e\'ye kadar belirli integrali kaç eder?', '1/3', ['1', 'e/3', '−1/3'], 'u = ln x ile ∫₀¹ u² du = 1/3.'),
  ('Karekök içinde 4 − x² bulunan kesrin, yani ∫ dx/√(4 − x²) ifadesinin antitürevi aşağıdakilerden hangisidir?', 'arcsin(x/2) + C', ['arcsin x + C', '2 arcsin(x/2) + C', '(1/2) arctan(x/2) + C'], 'x = 2u dönüşümüyle ∫ du/√(1 − u²) = arcsin u = arcsin(x/2).'),
  ('∫ 1/(x² + 9) dx aşağıdakilerden hangisidir?', '(1/3) arctan(x/3) + C', ['arctan(x/3) + C', '3 arctan(3x) + C', '(1/9) arctan x + C'], 'x = 3u ile dx = 3du ve ∫ 3du/(9(u² + 1)) = (1/3) arctan u.'),
  ('Payı eˣ, paydası 1 + eˣ olan kesri integre ettiğimizde hangi logaritmik ilkel ortaya çıkar?', 'ln(1 + eˣ) + C', ['ln(eˣ) + C', '1/(1 + eˣ) + C', 'eˣ·ln(1 + eˣ) + C'], 'Pay paydanın türevidir; ∫ u\'/u = ln|u| ve u = 1 + eˣ > 0.'),
  ('Kısmi integrasyon uygulandığında x ile kosinüsün çarpımının, yani ∫ x cos x dx ifadesinin sonucu hangisidir?', 'x sin x + cos x + C', ['x sin x − cos x + C', '−x sin x + cos x + C', 'x cos x + sin x + C'], 'u = x, dv = cos x dx alınırsa x sin x − ∫ sin x dx = x sin x + cos x.'),
  ('Sinüs eğrisi ile x doğrusunun çarpımından oluşan fonksiyonun 0\'dan π\'ye belirli integrali, parçalı integralle hesaplanırsa kaç çıkar?', 'π', ['2', 'π/2', '0'], '[−x cos x + sin x] = (−π·(−1) + 0) − 0 = π.'),
  ('Üssü negatif olan x·e^(−x) fonksiyonunun [0, 1] aralığındaki belirli integrali hangi değere eşittir?', '1 − 2/e', ['1 − 1/e', '2/e − 1', '1/e'], 'İlkel −(x + 1)e^(−x)\'dir. [−(x + 1)e^(−x)]₀¹ = −2/e + 1.'),
  ('Karekök terimi içeren x² + √x fonksiyonunun 0 ile 1 arasındaki belirli integrali kaç birimdir?', '1', ['2/3', '4/3', '1/2'], '∫₀¹ x² dx = 1/3 ve ∫₀¹ √x dx = 2/3. Toplam 1.'),
  ('Ters kare fonksiyonu 1/x² için 1\'den 2\'ye kadar alınan belirli integralin değeri nedir?', '1/2', ['1', '−1/2', '3/4'], '[−1/x]₁² = −1/2 + 1 = 1/2.'),
  ('Sekant karesi fonksiyonunun 0\'dan π/4\'e belirli integrali kaç eder?', '1', ['√2', 'π/4', '1/2'], '[tan x]₀^(π/4) = 1 − 0 = 1.'),
  ('1/(1 + x²) fonksiyonunun 0 ile 1 arasındaki belirli integrali için aşağıdakilerden hangisi doğrudur?', 'π/4', ['π/2', 'ln 2', '1/2'], '[arctan x]₀¹ = π/4 − 0.'),
  ('0\'dan 1/2\'ye 1/√(1 − x²) fonksiyonunun belirli integrali kaçtır?', 'π/6', ['π/3', 'π/4', '−π/6'], '[arcsin x]₀^(1/2) = π/6.'),
  ('1\'den 4\'e kadar 1/√x fonksiyonunun belirli integrali kaçtır?', '2', ['1', '3', '−2'], '∫ x^(−1/2) dx = 2√x. [2√x]₁⁴ = 4 − 2 = 2.'),
  ('Mutlak değer fonksiyonu |x − 1| için 0\'dan 2\'ye belirli integral kaçtır?', '1', ['0', '2', '1/2'], 'Aralık x = 1\'de ikiye bölünür; her parçanın alanı 1/2\'dir. Toplam 1.'),
  ('Yarım açı özdeşliğiyle sadeleşen kosinüs karesi fonksiyonu, 0 ile π/2 arasında integre edilirse hangi değer bulunur?', 'π/4', ['π/2', '1/2', '−π/4'], 'cos²x = (1 + cos 2x)/2 olduğundan [x/2 + sin 2x/4]₀^(π/2) = π/4.'),
  ('Üstel fonksiyon eˣ\'in 0\'dan ln 2\'ye belirli integrali kaçtır?', '1', ['2', 'ln 2', 'e'], '[eˣ]₀^(ln 2) = 2 − 1 = 1.'),
  ('Tek fonksiyon olan x³ için −2\'den 2\'ye belirli integral hakkında ne söylenir?', 'Sıfırdır; grafik orijine göre simetriktir', ['Pozitiftir', 'Negatiftir', 'Sekizdir'], 'Tek fonksiyonun orijine göre simetrik aralıktaki integrali, pozitif ve negatif alanlar birbirini götürdüğünden sıfırdır.'),
  ('−3\'ten 3\'e (x² + x) fonksiyonunun belirli integrali kaçtır?', '18', ['0', '9', '−18'], 'x terimi tek olduğundan 0 verir. x² çifttir: 2·∫₀³ x² dx = 2·9 = 18.'),
  ('Tek bir f fonksiyonu için ∫₋₂² [f(x) + 3] dx kaçtır?', '12', ['0', '6', '−12'], '∫ f = 0 (tek fonksiyon) ve ∫₋₂² 3 dx = 3·4 = 12.'),
  ('Bir sinüs kemerinin yüksekliği [0, π] aralığı boyunca ortalama olarak ne kadardır? Başka deyişle f(x) = sin x\'in bu aralıktaki ortalama değerini bulunuz.', '2/π', ['2', '1/π', 'π/2 − 1'], '∫₀^π sin x dx = 2 ve aralık uzunluğu π\'dir; ortalama 2/π.'),
  ('y = 1/x eğrisi, x ekseni, x = 1 ve x = e doğrularıyla çevrili bölgenin alanı kaçtır?', '1', ['e − 1', '1/e', 'ln 2'], '∫₁ᵉ dx/x = ln e − ln 1 = 1.'),
  ('y = √x eğrisi ile y = x/2 doğrusu arasında kalan sınırlı bölgenin alanı kaçtır?', '4/3', ['8/3', '2/3', '16/3'], 'Kesişimler x = 0 ve x = 4\'tür. ∫₀⁴ (√x − x/2) dx = 16/3 − 4 = 4/3.'),
  ('y = x doğrusunun x = 0 ile x = 2 arasındaki parçasının x ekseni etrafında döndürülmesiyle oluşan koninin hacmi kaçtır?', '8π/3', ['4π/3', '8π', '16π/3'], 'V = π∫₀² x² dx = π·8/3.'),
  ('y = x² eğrisi [0, 1] aralığında x ekseni etrafında döndürülüyor. Oluşan cismin hacmi nedir?', 'π/5', ['π/3', '2π/5', 'π/2'], 'V = π∫₀¹ x⁴ dx = π/5.'),
  ('F(x) = ∫₀ˣ e^(t²) dt biçiminde tanımlanan fonksiyonun türevi F\'(x) hangisidir?', 'e^(x²)', ['2x·e^(x²)', 'e^(x²)/(2x)', 'x²·e^(x²)'], 'Temel teoremin birinci kısmına göre sürekli bir f için d/dx ∫ₐˣ f(t) dt = f(x)\'tir.'),
  ('F(x) = ∫₀ˣ (t² + 1) dt fonksiyonu için F\'(2) değeri kaçtır?', '5', ['4', '10', '3'], 'F\'(x) = x² + 1 olduğundan F\'(2) = 5.'),
  ('Türevlenebilir bir f için f(1) = 2 ve f(4) = 7\'dir. ∫₁⁴ f\'(x) dx kaçtır?', '5', ['9', '14', '3'], 'Temel teoremin ikinci kısmı: ∫ₐᵇ f\' = f(b) − f(a) = 7 − 2 = 5.'),
  ('∫₀² x² dx integrali orta nokta kuralıyla n = 2 alt aralıkta yaklaşık hesaplanırsa sonuç kaç olur?', '2,5', ['3', '8/3', '2,25'], 'Orta noktalar 0,5 ve 1,5. h·[f(0,5) + f(1,5)] = 0,25 + 2,25 = 2,5.'),
  ('f(x) = x fonksiyonunun [0, 1] aralığında dört eşit parçaya bölünüp sol uç noktalarla alınan Riemann toplamı kaçtır?', '3/8', ['1/2', '5/8', '−3/8'], 'Her genişlik 1/4: (1/4)(0 + 1/4 + 1/2 + 3/4) = (1/4)(3/2) = 3/8.'),
  ('∫₁^∞ 1/x² dx genelleştirilmiş integralinin değeri kaçtır?', '1', ['∞', '2', '1/2'], 'lim (b → ∞) [−1/x]₁ᵇ = 0 − (−1) = 1.'),
  ('Üstel azalan e^(−2x) fonksiyonunun grafiği ile x ekseni arasında, x ≥ 0 için uzanan sonsuz bölgenin alanı kaçtır?', '1/2', ['2', '1', '1/10'], '[−e^(−2x)/2]₀^∞ = 0 − (−1/2) = 1/2.'),
  ('dy/dx = 2x ve y(0) = 1 koşullarını sağlayan fonksiyon için y(3) kaçtır?', '10', ['9', '7', '−10'], 'y = x² + C ve C = 1. y(3) = 9 + 1 = 10.'),
  ('f(x) = e^(2x) eğrisinin x = 0 noktasındaki teğetinin x eksenini kestiği noktanın apsisi kaçtır?', '−1/2', ['1/2', '−2', '2'], 'Teğet y = 2x + 1\'dir; y = 0 için x = −1/2.'),
  ('y = x³ − 3x eğrisinin yatay teğetinin bulunduğu nokta sayısı kaçtır?', '2', ['1', '3', '2,5'], 'y\' = 3x² − 3 = 0 → x = ±1; iki farklı noktada teğet yataydır.'),
  ('f(x) = x² − 2 için Newton yöntemiyle x₀ = 1 başlangıcından elde edilen x₁ kaçtır?', '3/2', ['1/2', '2', '−3/2'], 'x₁ = x₀ − f(x₀)/f\'(x₀) = 1 − (−1)/2 = 3/2.'),
  ('Periyodu 4 olan türevlenebilir bir fonksiyonun türevi için ne söylenebilir?', 'Türev de periyodiktir ve periyodu 4\'tür', ['Türev periyodik değildir', 'Türevin periyodu 2\'dir', 'Türev sabit olur'], 'f(x + 4) = f(x) eşitliğinin her iki yanı türetilirse f\'(x + 4) = f\'(x) elde edilir.'),
  ('Bir tanka giren suyun hızı r(t) = 6t litre/dakikadır. İlk 5 dakikada tanka kaç litre su girer?', '75', ['30', '150', '25'], 'Toplam su ∫₀⁵ 6t dt = 3t²\'nin 0\'dan 5\'e değeri = 75 litre.'),
  ('∫₀² f = 3 ve ∫₂⁵ f = 4 ise ∫₅⁰ f(x) dx kaçtır?', '−7', ['7', '1', '−1'], '∫₀⁵ f = 7 ve sınırlar ters çevrilince işaret değişir: ∫₅⁰ f = −7.'),
  ('Sabit fonksiyon 5 için ∫₋₁³ 5 dx değeri kaçtır?', '20', ['15', '5', '−20'], 'Sabit fonksiyonun integrali yükseklik çarpı aralık uzunluğudur: 5·4 = 20.'),
  ('∫ sec x tan x dx integrali nedir?', 'sec x + C', ['tan x + C', 'sec²x + C', '−sec x + C'], 'sec x\'in türevi sec x tan x olduğu için ilkel sec x + C\'dir.'),
  ('1/sin²x fonksiyonunun belirsiz integrali nedir?', '−cot x + C', ['cot x + C', 'tan x + C', '−1/sin x + C'], 'cot x\'in türevi −1/sin²x olduğundan ilkel −cot x + C\'dir.'),
  ('Aşağıdaki ifadelerden hangisi belirsiz bir biçim değildir?', '∞ + ∞', ['∞ − ∞', '0/0', '1^∞'], 'İki sınırsız artan büyüklüğün toplamı daima sonsuza gider; belirsizlik yoktur. ∞ − ∞ ise belirsizdir.'),
  ('Marjinal maliyet kavramı için C(x) = 0,01x² + 4x + 500 toplam maliyet fonksiyonunda x = 100 iken C\'(100) yaklaşık neyi verir?', '6', ['500', '4', '1000'], 'C\'(x) = 0,02x + 4 olduğundan C\'(100) = 6 lira; 101. birimin yaklaşık ek maliyetidir.'),
  ('Bir hesap makinesiyle x = 0,001 için (1 + x)^(1/x) değeri yaklaşık 2,7169 bulunuyor. x → 0 iken bu ifadenin limitine ilişkin en uygun tahmin hangisidir?', 'e ≈ 2,718', ['2', '3', '2,7169 tam değerdir'], '(1 + x)^(1/x) ifadesinin x → 0 iken limiti e sayısıdır; sayısal değer buna çok yakındır.'),
  ('f(x) = x² + 1 ise f\'(f(1)) kaçtır?', '4', ['2', '5', '−4'], 'f(1) = 2 ve f\'(x) = 2x olduğundan f\'(2) = 4.'),
  ('Bir cismin konumu metre, zamanı saniye cinsinden verilmiştir. Konumun zamana göre türevi hangi birimle ifade edilir?', 'm/s (metre bölü saniye)', ['m·s (metre çarpı saniye)', 'm/s² (metre bölü saniye kare)', 's/m (saniye bölü metre)'], 'Türev, değişim hızıdır; konum değişimi bölü zaman değişimi olduğundan birim m/s\'dir.'),
  ('Bir ürünün toplam maliyeti C(x) TL, üretim miktarı x adet olduğuna göre C\'(x) hangi birime sahiptir?', 'TL/adet', ['TL·adet', 'adet/TL', 'TL'], 'Türev, maliyetin üretim miktarına göre değişim hızıdır: TL bölü adet.'),
  ('Bir cismin hız–zaman fonksiyonunun belirli integrali (zamana göre) hangi niceliği verir?', 'Yer değiştirmeyi', ['İvmeyi', 'Hızın ortalamasını', 'Kütleyi'], '∫ v dt, konumdaki net değişimi yani yer değiştirmeyi verir.'),
  ('Bir elektrik cihazının güç (kW) – zaman (saat) fonksiyonunun belirli integrali neyi verir?', 'Harcanan toplam enerjiyi', ['Anlık voltajı', 'Cihazın verimini', 'Ortalama akımı'], 'Güç, enerjinin zamana göre türevidir; güç–zaman grafiğinin altındaki alan toplam enerjiyi (kWh) verir.'),
  ('Sürekli bileşik faizle yıllık %5 getiri sağlayan 100 TL\'lik yatırım için A(t) = 100e^(0,05t) ise 20 yıl sonraki tutar kaç TL\'dir?', '100e', ['100e²', '200', '2000'], '0,05·20 = 1 olduğundan A(20) = 100e¹ = 100e.'),
  ('∫₀⁴ (4 − x) dx integralinin değeri, oluşan üçgenin alanı düşünülerek bulunursa kaçtır?', '8', ['16', '4', '12'], 'Taban 4, yükseklik 4 olan dik üçgenin alanı (1/2)·4·4 = 8\'dir.'),
  ('Negatif bir x için 1/x fonksiyonunun ilkelini yazarken logaritma argümanının tanımlı kalması için hangi biçim kullanılmalıdır? (C sabittir)', 'ln|x| + C', ['ln x + C', '−1/x² + C', '1/x² + C'], 'x < 0 iken ln x tanımsızdır; ln|x|\'in türevi her x ≠ 0 için 1/x\'tir.'),
  ('Bir tam sinüs kemerinin, yani 0\'dan π\'ye sin²x eğrisinin altında kalan alan, yarım açı formülüyle hesaplanırsa kaç birimkare bulunur?', 'π/2', ['π', '1', 'π/10'], 'sin²x = (1 − cos 2x)/2; [x/2 − sin 2x/4]₀^π = π/2.'),
  ('x cos x fonksiyonunun −1\'den 1\'e belirli integrali hakkında ne söylenebilir?', 'Sıfırdır, çünkü fonksiyon tektir', ['Pozitiftir, çünkü kosinüs pozitiftir', 'Negatiftir', 'İkidir'], 'x tek, cos x çift olduğundan çarpım tektir. Simetrik aralıkta tek fonksiyonun integrali 0\'dır.'),
  ('[1, 5] aralığı n = 4 eşit parçaya bölünürse her alt aralığın genişliği Δx kaç olur?', '1', ['4', '5/4', '1/4'], 'Δx = (b − a)/n = (5 − 1)/4 = 1.'),
  ('Teğet doğrusuyla yaklaşım yapılarak e^(0,1) değeri yaklaşık kaç bulunur?', '1,1', ['1,01', '1,2', '1,0'], 'f(x) = eˣ ve f(0) = f\'(0) = 1. e^(0,1) ≈ 1 + 0,1 = 1,1.'),
  ('Karekök fonksiyonunun 4 noktasındaki teğeti kullanılarak, hesap makinesi olmadan 4,04 sayısının kareköküne yaklaşık değer bulunuz.', '2,01', ['2,04', '2,001', '2,1'], 'f(x) = √x, f\'(4) = 1/4. √4,04 ≈ 2 + 0,04/4 = 2,01.'),
];
